import{_ as d,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"صارفین کے تحفظ کا قانون","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0042-消费者保护法.md","filePath":"ur/0042-消费者保护法.md"}'),e={name:"ur/0042-消费者保护法.md"};function i(o,t,h,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="صارفین-کے-تحفظ-کا-قانون" tabindex="-1">صارفین کے تحفظ کا قانون <a class="header-anchor" href="#صارفین-کے-تحفظ-کا-قانون" aria-label="Permalink to &quot;صارفین کے تحفظ کا قانون&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>42</td></tr><tr><td>ماڈیول</td><td>قانونی نظام اور گورننس کا فریم ورک</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>صارف کے حقوق، منصفانہ لین دین، دھوکہ دہی مخالف، مصنوعات کی ذمہ داری، سمبیوسس بازار</td></tr></tbody></table><h2 id="أولاً-قانون-سازی-کا-مقصد-اور-اطلاق-کی-حد" tabindex="-1">أولاً. قانون سازی کا مقصد اور اطلاق کی حد <a class="header-anchor" href="#أولاً-قانون-سازی-کا-مقصد-اور-اطلاق-کی-حد" aria-label="Permalink to &quot;أولاً. قانون سازی کا مقصد اور اطلاق کی حد&quot;">​</a></h2><p>《صارفین کے تحفظ کا قانون》 اینکر سمبیوسس تہذیب کے قانونی نظام میں بنیادی قوانین میں سے ایک ہے، اور 《سمبیوسس لیبر قانون》 کے ساتھ مل کر معاشی زندگی کے دو ستون بناتا ہے۔ اس قانون کا مقصد ہینگیوانژو کے اندر تمام صارفین کے جائز حقوق کی حفاظت کرنا، بازار کے لین دین کے رویے کو منظم کرنا، منصفانہ، دیانتدارانہ، سمبیوسس بازار کا نظام برقرار رکھنا، اور لوٹ مار کے تجارتی رویے کی طرف سے تمام مخلوق کے حقوق کی خلاف ورزی کو روکنا ہے۔</p><p>یہ قانون ہینگیوانژو کے اندر تمام ان صارفین پر لاگو ہوتا ہے جو ذاتی یا خاندانی زندگی کی ضروریات کو پورا کرنے کے لیے سامان خریدتے، استعمال کرتے یا خدمات حاصل کرتے ہیں، اور ان آپریٹرز پر بھی جو صارفین کو سامان یا خدمات فراہم کرتے ہیں۔ بین سطحی لین دین پر بھی یہ قانون لاگو ہوتا ہے، لیکن سطح کے فرق کے مطابق نفاذ کے تفصیلی اصول بنائے جا سکتے ہیں۔</p><h2 id="ثانياً-صارف-کے-بنیادی-حقوق" tabindex="-1">ثانياً. صارف کے بنیادی حقوق <a class="header-anchor" href="#ثانياً-صارف-کے-بنیادی-حقوق" aria-label="Permalink to &quot;ثانياً. صارف کے بنیادی حقوق&quot;">​</a></h2><p>یہ قانون صارفین کو درج ذیل نو بنیادی حقوق عطا کرتا ہے:</p><table tabindex="0"><thead><tr><th>حق</th><th>مواد</th></tr></thead><tbody><tr><td>تحفظ کی سلامتی کا حق</td><td>صارف سامان خریدتے، استعمال کرتے اور خدمات حاصل کرتے وقت ذاتی، جائیداد کی سلامتی کو نقصان نہ پہنچانے کا حق رکھتا ہے</td></tr><tr><td>حقیقت جاننے کا حق</td><td>صارف کو اس کا حق ہے کہ وہ اپنے خریدے، استعمال کردہ سامان یا حاصل کردہ خدمات کی حقیقی صورتحال جانے، بشمول اجزاء، افادیت، خطرات وغیرہ</td></tr><tr><td>خود مختار انتخاب کا حق</td><td>صارف کو خود مختار طور پر سامان یا خدمات منتخب کرنے کا حق ہے، موازنہ، شناخت اور انتخاب کرنے کا حق ہے، اور جبری لین دین سے انکار کر سکتا ہے</td></tr><tr><td>منصفانہ لین دین کا حق</td><td>صارف کو معیار کی ضمانت، مناسب قیمت، درست پیمائش وغیرہ جیسے منصفانہ لین دین کی شرائط حاصل کرنے کا حق ہے</td></tr><tr><td>قانون کے مطابق معاوضے کا حق</td><td>صارف جب سامان خریدنے، استعمال کرنے یا خدمات حاصل کرنے کی وجہ سے ذاتی، جائیداد کا نقصان اٹھاتا ہے تو اسے قانون کے مطابق معاوضہ حاصل کرنے کا حق ہے</td></tr><tr><td>تنظیم بنا کر حقوق کی دفاع کا حق</td><td>صارف کو قانون کے مطابق صارف کی تنظیم بنانے یا اس میں شامل ہونے کا حق ہے، اور اپنے جائز حقوق کی دفاع کر سکتا ہے</td></tr><tr><td>علم حاصل کرنے کا حق</td><td>صارف کو استهلاک اور صارف کے حقوق کے تحفظ سے متعلق علم اور معلومات حاصل کرنے کا حق ہے</td></tr><tr><td>احترام کا حق</td><td>صارف سامان خریدتے، استعمال کرتے اور خدمات حاصل کرتے وقت ذاتی وقار، نسلی رسم و رواج کے احترام کا حق رکھتا ہے</td></tr><tr><td>نگرانی کا حق</td><td>صارف کو سامان اور خدمات اور صارف کے حقوق کے تحفظ کے کام کی نگرانی کرنے، تنقید اور تجاویز دینے کا حق ہے</td></tr></tbody></table><h2 id="ثالثاً-آپریٹر-کی-ذمہ-داریاں" tabindex="-1">ثالثاً. آپریٹر کی ذمہ داریاں <a class="header-anchor" href="#ثالثاً-آپریٹر-کی-ذمہ-داریاں" aria-label="Permalink to &quot;ثالثاً. آپریٹر کی ذمہ داریاں&quot;">​</a></h2><p>آپریٹر کو صارفین کو سامان یا خدمات فراہم کرتے وقت درج ذیل ذمہ داریاں ادا کرنی چاہئیں:</p><ol><li><strong>قانون کے مطابق کاروبار کرنے کی ذمہ داری</strong>: آپریٹر کو آئین اور قانون کی تعمیل کرنی چاہیے، اور منظور شدہ کاروبار کے دائرے میں کاروباری سرگرمیاں چلانی چاہئیں۔</li><li><strong>سلامتی کی ضمانت کی ذمہ داری</strong>: آپریٹر کو اس بات کو یقینی بنانا چاہیے کہ اس کی فراہم کردہ سامان یا خدمات ذاتی، جائیداد کی سلامتی کی ضمانت کے تقاضوں کو پوری کرتی ہیں، اور ممکنہ طور پر سلامتی کو خطرے میں ڈالنے والے سامان اور خدمات کے بارے میں حقیقی وضاحت اور واضح انتباہ دینا چاہیے۔</li><li><strong>حقیقی معلومات کی ذمہ داری</strong>: آپریٹر کو صارفین کو سامان یا خدمات سے متعلق حقیقی معلومات فراہم کرنی چاہئیں، اور جھوٹی یا گمراہ کن تشہیر نہیں کرنی چاہیے۔ سادھنہ قسم کے سامان اور خدمات میں افادیت کی حدود اور ممکنہ خطرات کو حقیقت کے مطابق نشان زد کرنا ضروری ہے۔</li><li><strong>معیار کی ضمانت کی ذمہ داری</strong>: آپریٹر کو اس بات کو یقینی بنانا چاہیے کہ سامان کے معمول کے استعمال یا خدمات کے حصول کی صورت میں، اس کی فراہم کردہ سامان یا خدمات میں وہ معیار، کارکردگی، استعمال اور میعاد ہونی چاہیے جو ہونی چاہیے۔</li><li><strong>منصفانہ لین دین کی ذمہ داری</strong>: آپریٹر فارمیٹ کی شرائط، نوٹس، اعلان، دکان کے اعلان وغیرہ کے ذریعے صارف کے حقوق کو خارج یا محدود کرنا، آپریٹر کی ذمہ داری کو کم کرنا یا معاف کرنا، صارف کی ذمہ داری کو بڑھانا وغیرہ جیسے صارف کے لیے غیر منصفانہ، غیر معقول احکام نہیں بنا سکتا۔</li><li><strong>بیچ کے بعد کی خدمات کی ذمہ داری</strong>: آپریٹر کو ریاست کی دفعات یا صارف کے ساتھ معاہدے کے مطابق، مرمت، تبدیلی، واپسی اور دیگر بیچ کے بعد کی خدمات کی ذمہ داری اٹھانی چاہیے۔</li><li><strong>رازداری کے تحفظ کی ذمہ داری</strong>: آپریٹر کو صارف کی ذاتی معلومات اور شعور کے ڈیٹا کی حفاظت کرنی چاہیے، اور صارف کی رضامندی کے بغیر جمع، استعمال یا لیک نہیں کر سکتا۔</li></ol><h2 id="رابعاً-تنازعات-کا-حل-اور-قانونی-ذمہ-داری" tabindex="-1">رابعاً. تنازعات کا حل اور قانونی ذمہ داری <a class="header-anchor" href="#رابعاً-تنازعات-کا-حل-اور-قانونی-ذمہ-داری" aria-label="Permalink to &quot;رابعاً. تنازعات کا حل اور قانونی ذمہ داری&quot;">​</a></h2><p>جب صارف اور آپریٹر کے درمیان صارف کے حقوق کا تنازعہ پیدا ہوتا ہے تو اسے درج ذیل ذرائع سے حل کیا جا سکتا ہے:</p><ul><li>آپریٹر کے ساتھ مذاکرات اور مفاہمت</li><li>صارف کی تنظیم سے ثالثی کی درخواست</li><li>متعلقہ انتظامی محکمے میں شکایت</li><li>آپریٹر کے ساتھ طے شدہ ثالثی کے معاہدے کے مطابق ثالثی ادارے میں ثالثی کی درخواست</li><li>سمبیوسس عدالت میں مقدمہ دائر کرنا</li></ul><p>آپریٹر جو اس قانون کی دفعات کی خلاف ورزی کر کے صارف کے جائز حقوق کی خلاف ورزی کرتا ہے، اسے درج ذیل ذمہ داری اٹھانی ہوگی:</p><table tabindex="0"><thead><tr><th>غیر قانونی کارروائی</th><th>قانونی ذمہ داری</th></tr></thead><tbody><tr><td>نقص دہ سامان یا خدمات فراہم کر کے نقصان پہنچانا</td><td>معاوضے کی ذمہ داری اٹھانا، بشمول طبی اخراجات، کام سے محرومی کا معاوضہ، معذوری کا معاوضہ وغیرہ</td></tr><tr><td>دھوکہ دہی کا عمل</td><td>صارف کی درخواست کے مطابق معاوضہ بڑھانا، رقم صارف کی خریدی گئی سامان کی قیمت یا حاصل کردہ خدمات کی فیس کا تین گنا ہے</td></tr><tr><td>جھوٹی تشہیر</td><td>غیر قانونی کارروائی بند کرنے کا حکم، اثر ختم کرنا، جرمانہ</td></tr><tr><td>جبری لین دین</td><td>اصلاح کا حکم، غیر معقول فیس واپس کرنا، جرمانہ</td></tr><tr><td>صارف کی رازداری کی خلاف ورزی</td><td>ذہنی نقصان کا معاوضہ اٹھانا، سنگین صورتوں میں مجرمانہ ذمہ داری</td></tr></tbody></table><h2 id="خامساً-صارف-کی-تنظیمیں-اور-سماجی-نگرانی" tabindex="-1">خامساً. صارف کی تنظیمیں اور سماجی نگرانی <a class="header-anchor" href="#خامساً-صارف-کی-تنظیمیں-اور-سماجی-نگرانی" aria-label="Permalink to &quot;خامساً. صارف کی تنظیمیں اور سماجی نگرانی&quot;">​</a></h2><p>ریاست تمام تنظیموں اور افراد کی حوصلہ افزائی اور حمایت کرتی ہے کہ وہ صارف کے جائز حقوق کو نقصان پہنچانے والے رویے کی سماجی نگرانی کریں۔ صارفین کی انجمن ایک سماجی تنظیم ہے جو قانون کے مطابق قائم کی گئی ہے جو سامان اور خدمات کی سماجی نگرانی کرتی ہے اور صارف کے جائز حقوق کی حفاظت کرتی ہے، اور درج ذیل افعال انجام دیتی ہے:</p><ol><li>صارفین کو استهلاک کی معلومات اور مشاورتی خدمات فراہم کرنا</li><li>متعلقہ انتظامی محکمے کی طرف سے سامان اور خدمات کی نگرانی، معائنہ میں حصہ لینا</li><li>صارف کے جائز حقوق سے متعلق مسائل پر متعلقہ انتظامی محکمے کو رپورٹ کرنا، دریافت کرنا، تجاویز دینا</li><li>صارف کی شکایات وصول کرنا، اور شکایت کے معاملات کی تحقیق، ثالثی کرنا</li><li>صارف کے جائز حقوق کو نقصان پہنچانے والے رویے کے خلاف، نقصان اٹھانے والے صارفین کی مقدمہ دائر کرنے میں مدد کرنا</li></ol><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>《صارفین کے تحفظ کا قانون》 اینکر سمبیوسس تہذیب کے بازار کے نظام کا محافظ ہے۔ یہ صارفین کو کافی حقوق عطا کر کے، آپریٹرز کے رویے کو محدود کر کے، اور متنوع تنازعات کے حل کا طریقہ کار قائم کر کے، اس بات کو یقینی بناتا ہے کہ بازار کا لین دین منصفانہ، دیانتدارانہ، سمبیوسس کی راہ پر چلے، اور تجارتی شعبے کو لوٹ مار کے رویے کی نئی جڑ بننے سے روکے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>40-共生宪法总纲 (سمبیوسس آئین کے بنیادی اصول)</li><li>41-共生劳动法 (سمبیوسس لیبر قانون)</li><li>47-反垄断法 (اجارہ داری مخالف قانون)</li><li>36-社会结构与阶层流动 (سماجی ڈھانچہ اور طبقاتی نقل و حرکت)</li></ul>',23)])])}const u=d(e,[["render",i]]);export{_ as __pageData,u as default};
